        </div>
      )}
      {/* 사용자가 기다림을 풀려면 가야 할 곳(예: 로그인 계정 등록·허용) — 사유만 주고 끝내지 않는다.
          재시작으로 waiting-user → interrupted 가 돼도 이 버튼이 사라지면 갈 곳을 잃으므로 함께 보인다. */}
      {(t.state === 'waiting-user' || t.state === 'interrupted') && t.waitActionUrl && (
