#!/usr/bin/env node
// probe-ptask-card.mjs — 일회성 진단: "IPC 로 만든 영속 작업이 AI 사이드바 카드로 그려지는가".
// verify-task-target-ui-cdp.mjs 개발 중, 작업이 IPC 목록에는 있는데 화면엔 카드가 0개인 현상을
// 최소 조건으로 좁히기 위한 스크립트다(게이트 미등록).

import { spawn, execFileSync } from 'node:child_process'
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { connectShellSessionReady, waitForPortFree } from './lib/cdp.mjs'
import { startFakeLlm } from './lib/fake-llm.mjs'
import { getFreePorts, preferFreePort } from './lib/ports.mjs'
import { startWindowTabsFixtureServer } from './window-tabs-fixture-server.mjs'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const REPO = path.resolve(__dirname, '..')
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))
const J = JSON.stringify

const out = path.join(REPO, 'verify-out', 'probe-ptask-card')
const appExe = path.join(REPO, 'dist', 'win-unpacked', 'ezBrowser.exe')

async function main() {
  fs.mkdirSync(out, { recursive: true })
  const port = await preferFreePort(9299, 'probe-ptask-card')
  await waitForPortFree(port)
  const [llmPort, fxPort] = await getFreePorts(2)
  const llm = await startFakeLlm({ port: llmPort, script: [{ reply: () => J({ action: 'done', message: '끝' }) }] })
  const fx = await startWindowTabsFixtureServer(fxPort)

  const profileDir = path.join(out, 'profile')
  fs.rmSync(profileDir, { recursive: true, force: true })
  fs.mkdirSync(profileDir, { recursive: true })
  fs.writeFileSync(path.join(profileDir, 'settings.json'), J({
    setup: { completed: true }, startup: { mode: 'newtab', urls: [] }, adblock: { enabled: false },
    ai: {
      enabled: true, provider: 'ollama', ollamaUrl: llm.url, ollamaModel: 'test-model',
      agentMaxSteps: 4, agentVision: 'off', agentCollapsePanels: false,
    },
  }, null, 2))

  const log = fs.createWriteStream(path.join(out, 'app.log'))
  const child = spawn(appExe, [`--remote-debugging-port=${port}`, `--user-data-dir=${profileDir}`],
    { stdio: ['ignore', 'pipe', 'pipe'] })
  child.stdout.pipe(log); child.stderr.pipe(log)

  let shell = null
  try {
    shell = await connectShellSessionReady(port)
    const ev = async (expr, awaitP = false) => {
      const r = await shell.send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: awaitP }, 30000)
      if (r.exceptionDetails) throw new Error(`예외: ${r.exceptionDetails.exception?.description ?? r.exceptionDetails.text}`)
      return r.result?.result?.value ?? r.result?.value
    }
    const jv = async (expr) => JSON.parse(await ev(`Promise.resolve(${expr}).then(v=>JSON.stringify(v===undefined?null:v))`, true) ?? 'null')

    const windowId = await ev('new URL(location.href).searchParams.get("windowId")')
    console.log('windowId =', windowId)

    // 1) AI 패널 열기
    await jv(`window.browserAPI.actions.run('action.ai.open', ${J({ windowId })})`)
    for (let i = 0; i < 40 && !(await ev(`!!document.querySelector('.ai-tab')`)); i++) await sleep(500)
    console.log('.ai-tab 마운트 =', await ev(`!!document.querySelector('.ai-tab')`))

    // 2) 탭 하나 만들고 그 탭에 작업 생성(IPC) — UI 를 거치지 않는다.
    const tab = await jv(`window.browserAPI.tabs.create(${J(windowId)}, ${J(`${fx.base}/page?slot=probe`)}, ${J({ background: true })})`)
    await sleep(1500)
    const created = await jv(`window.browserAPI.ai.ptaskCreate(${J({ instruction: '[PROBE] 카드가 그려지는가', tabId: tab.id })})`)
    console.log('작업 생성 =', created?.id, created?.state)

    // 3) 카드가 뜨는지 최대 15초 기다린다
    let cards = 0
    for (let i = 0; i < 30; i++) {
      cards = await ev(`document.querySelectorAll('.ai-task-card').length`)
      if (cards > 0) break
      await sleep(500)
    }
    const ipcLen = (await jv(`window.browserAPI.ai.ptaskList()`))?.length
    console.log(`>> 카드 수=${cards} · IPC 목록 길이=${ipcLen}`)
    console.log('   ai-body 앞부분 =', String(await ev(`(document.querySelector('.ai-body')?.innerHTML||'(없음)').slice(0,160)`)))

    // 4) 시작까지 하면 달라지는가(상태 변화 broadcast)
    if (created?.id) {
      await jv(`window.browserAPI.ai.ptaskStart(${J(created.id)})`)
      await sleep(3000)
      console.log('   시작 후 카드 수 =', await ev(`document.querySelectorAll('.ai-task-card').length`))
    }
  } finally {
    try { shell?.close() } catch { /* ignore */ }
    try { execFileSync('taskkill', ['/PID', String(child.pid), '/T', '/F'], { stdio: 'ignore' }) } catch { /* ignore */ }
    await sleep(500)
    try { await fx.close() } catch { /* ignore */ }
    try { await llm.close() } catch { /* ignore */ }
  }
}
main().catch((e) => { console.error(e); process.exit(2) })

