  const snapProbe = await domSnapshot()
  note(`[A] 새 작업 생성으로 흔든 뒤 렌더러 구독 수신=${J(probe)} · 카드 수=${snapProbe?.cards} · IPC 목록=${snapProbe?.ipcTasks?.length}`)
